import checkpoints from "./colfax-checkpoints.json";

type LatLng = google.maps.LatLngLiteral;

/**
 * Points on each side of Colfax Ave (US-40), west to east, that Google routes
 * through without leaving Colfax. Generated by scripts/colfax-checkpoints.ts
 * from OpenStreetMap data, © OpenStreetMap contributors (ODbL).
 */
const { eastbound: EASTBOUND, westbound: WESTBOUND } = checkpoints;

// Closer than this, one waypoint is enough.
const MIN_COLFAX_STRETCH_KM = 1.5;
// Waypoints this far apart keep the route on Colfax instead of crossing it.
const WAYPOINT_SPACING_KM = 3;
// Routes API bills more than 10 intermediate waypoints at a higher tier.
const MAX_WAYPOINTS = 10;

const KM_PER_DEGREE_LNG = 111.32 * Math.cos((39.74 * Math.PI) / 180);

const nearest = (points: LatLng[], lng: number) =>
  points.reduce((best, point) =>
    Math.abs(point.lng - lng) < Math.abs(best.lng - lng) ? point : best,
  );

/**
 * Returns waypoints that keep a trip on Colfax: checkpoints on the side of
 * Colfax the trip drives, about evenly spaced between the start's and the
 * end's longitudes.
 */
export function colfaxWaypoints(start: LatLng, end: LatLng): LatLng[] {
  const side = end.lng > start.lng ? EASTBOUND : WESTBOUND;
  const west = side[0]!.lng;
  const east = side.at(-1)!.lng;
  const clamp = (lng: number) => Math.min(Math.max(lng, west), east);
  const enter = clamp(start.lng);
  const exit = clamp(end.lng);

  const between = side.filter(
    ({ lng }) => Math.min(enter, exit) <= lng && lng <= Math.max(enter, exit),
  );
  const candidates = between.length > 0 ? between : side;

  const stretchKm = Math.abs(exit - enter) * KM_PER_DEGREE_LNG;
  if (stretchKm < MIN_COLFAX_STRETCH_KM) {
    return [nearest(candidates, (enter + exit) / 2)];
  }

  const count = Math.min(
    Math.ceil(stretchKm / WAYPOINT_SPACING_KM) + 1,
    MAX_WAYPOINTS,
  );
  const waypoints = Array.from({ length: count }, (_, i) =>
    nearest(candidates, enter + ((exit - enter) * i) / (count - 1)),
  );
  return [...new Set(waypoints)];
}
